/**
 * harness-guard.ts — omp hook generated by harness-init
 *
 * Discovery: omp loads project hooks from `<project>/.omp/hooks/pre/*.ts`
 * and user hooks from `~/.omp/agent/hooks/pre/*.ts`. A factory placed
 * directly in `.omp/hooks/` is not discovered — keep it under `pre/`.
 * omp rediscovers agents and hooks before each spawn; no restart is needed.
 *
 * This hook is self-contained TypeScript. It never calls `bash`, `sh`, `jq`,
 * or the `.harness/scripts/` helpers, because those dependencies are not
 * reliably available inside omp on Windows. The shell guards remain in the
 * repository for manual and CI use.
 *
 * Responsibilities (all state paths resolve against the session cwd):
 * - `before_agent_start` injects the harness cursor (epic / sprint / phase /
 *   goal / next_action) plus the progress tail as a hidden custom message.
 * - `tool_call` matches `bash` commands (and `edit` / `write` paths) against
 *   `.harness/tier-a-patterns.txt` at the configured `hook_level`
 *   (strict = deny, warn = log only, minimal = off). At `strict` it also
 *   gates `mcp__*` tools against `allowed_mcp_servers`.
 * - `tool_result` records edit/write calls in `.harness/progress.md`.
 * - `session.compacting` re-injects state + progress tail.
 * - `session_stop` ports the Principal Skinner decision matrix and returns
 *   `{decision:"block", reason}` while the loop is incomplete. It returns
 *   early when `event.stop_hook_active` is set.
 *
 * Limits of `session_stop`: it never fires for task/subagent sessions, and a
 * refusal stays blocking until the hook allows completion or the operator
 * interrupts. It cannot resume or revive a killed process.
 */

import { appendFileSync, existsSync, mkdirSync, readFileSync, readdirSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import type { HookAPI } from "@oh-my-pi/pi-coding-agent/extensibility/hooks";

const HARNESS_DIR = ".harness";
const CONFIG_FILE = ".harness/_config.yml";
const STATE_FILE = ".harness/_state.json";
const PROGRESS_FILE = ".harness/progress.md";
const TOOL_LOG_FILE = ".harness/tool_log.jsonl";
const PATTERNS_FILE = ".harness/tier-a-patterns.txt";
const AUDIT_FILE = ".harness/_audit/tier_a_history.jsonl";
const WILDCARD_MARKER = ".harness/.mcp-wildcard-warned";

const CONTEXT_PROGRESS_LINES = 8;
const DEFAULT_MAX_ITERATIONS = 8;
const DEFAULT_MAX_WALL_TIME_SEC = 28800;
const DEFAULT_MAX_COST_USD = 20;
const DEFAULT_RUBRIC_STAGNATION_N = 3;

const NON_LOOP_PHASES: Record<string, true> = {
  "product-spec-draft": true,
  "roadmap-draft": true,
  "roadmap-approved": true,
  "issues-pending": true,
  "ready-for-loop": true,
  done: true,
  "foundation-setup": true,
  "foundation-attest": true,
};

type HookLevel = "strict" | "warn" | "minimal";
type JsonObject = Record<string, unknown>;

interface HarnessConfig {
  hookLevel: HookLevel;
  maxIterations?: string;
  maxWallTimeSec?: string;
  maxCostUsd?: string;
  rubricStagnationN?: string;
  allowedMcpServers?: string[];
  allowedMcpServersCustom?: string;
  progressTailLines?: string;
  toolLogExternal: boolean;
  missing: boolean;
  malformed: boolean;
}

interface TierMatch {
  pattern: string;
  subject: string;
}

/** Contexts that already received a visible warning. */
const warned = new Set<string>();
/** Last injected context per session, so identical state does not accumulate. */
const lastInjectedContext = new Map<string, string>();

function readText(path: string): string | null {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return null;
  }
}

function readJson(path: string): JsonObject | null {
  const text = readText(path);
  if (!text) return null;
  try {
    const parsed: unknown = JSON.parse(text);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? (parsed as JsonObject) : null;
  } catch {
    return null;
  }
}

function writeJsonAtomic(path: string, value: JsonObject): void {
  const tmp = `${path}.tmp-${process.pid}-${Date.now()}`;
  writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, "utf8");
  renameSync(tmp, path);
}

function asString(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : fallback;
}

function asNumber(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function asBoolean(value: unknown): boolean {
  return value === true;
}

function loggerWarn(pi: object, message: string): void {
  if (!("logger" in pi)) return;
  const logger = pi.logger;
  if (!logger || typeof logger !== "object" || !("warn" in logger)) return;
  const warn = logger.warn;
  if (typeof warn === "function") warn(message);
}

/** Surface a configuration problem once per session instead of failing silently. */
function warnOnce(pi: HookAPI, ctx: object, key: string, message: string): void {
  if (warned.has(key)) return;
  warned.add(key);
  try {
    if ("ui" in ctx) {
      const ui = ctx.ui;
      if (ui && typeof ui === "object" && "notify" in ui && typeof ui.notify === "function") {
        ui.notify(`harness-guard: ${message}`, "warning");
      }
    }
  } catch {
    // UI is optional in headless sessions.
  }
  try {
    loggerWarn(pi, `harness-guard: ${message}`);
  } catch {
    // Logging must never break the hook.
  }
}

function stripScalar(value: string): string {
  return value
    .replace(/\s+#.*$/, "")
    .trim()
    .replace(/^["']|["']$/g, "");
}

/** Parse the small YAML subset harness-init writes, without a YAML dependency. */
function readConfig(pi: HookAPI, ctx: object, cwd: string): HarnessConfig {
  const config: HarnessConfig = { hookLevel: "strict", toolLogExternal: false, missing: true, malformed: false };
  const text = readText(join(cwd, CONFIG_FILE));
  if (text === null) {
    warnOnce(pi, ctx, "config-missing", `${CONFIG_FILE} is missing; defaulting hook_level=strict and denying MCP calls`);
    return config;
  }

  config.missing = false;
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  let sawHookLevel = false;
  let listKey: string | null = null;
  const listValues: string[] = [];

  for (const line of lines) {
    if (!line.trim() || line.trim().startsWith("#")) continue;

    const listItem = /^\s*-\s*(.+)$/.exec(line);
    if (listItem && listKey) {
      listValues.push(stripScalar(listItem[1]));
      continue;
    }

    const pair = /^([A-Za-z0-9_]+):\s*(.*)$/.exec(line);
    if (!pair) {
      listKey = null;
      continue;
    }

    const key = pair[1];
    const value = pair[2].trim();
    if (listKey === "allowed_mcp_servers" && key !== "allowed_mcp_servers") {
      config.allowedMcpServers = listValues;
      listKey = null;
    }

    if (value === "") {
      listKey = key;
      listValues.length = 0;
      continue;
    }
    listKey = null;

    if (key === "hook_level") {
      const level = stripScalar(value);
      if (level === "strict" || level === "warn" || level === "minimal") {
        config.hookLevel = level;
        sawHookLevel = true;
      }
    } else if (key === "max_iterations") {
      config.maxIterations = stripScalar(value);
    } else if (key === "max_wall_time_sec") {
      config.maxWallTimeSec = stripScalar(value);
    } else if (key === "max_cost_usd") {
      config.maxCostUsd = stripScalar(value);
    } else if (key === "rubric_stagnation_n") {
      config.rubricStagnationN = stripScalar(value);
    } else if (key === "progress_tail_lines") {
      config.progressTailLines = stripScalar(value);
    } else if (key === "tool_log_external") {
      config.toolLogExternal = stripScalar(value) === "true";
    } else if (key === "allowed_mcp_servers") {
      const inline = stripScalar(value);
      if (inline.startsWith("[")) {
        config.allowedMcpServers = inline
          .replace(/^\[|\]$/g, "")
          .split(",")
          .map(item => item.trim().replace(/^["']|["']$/g, ""))
          .filter(Boolean);
      } else if (inline) {
        config.allowedMcpServers = inline.split(/[\s,]+/).filter(Boolean);
      }
    } else if (key === "allowed_mcp_servers_custom") {
      const custom = stripScalar(value);
      if (custom) config.allowedMcpServersCustom = custom;
    }
  }

  if (listKey === "allowed_mcp_servers" && listValues.length > 0) {
    config.allowedMcpServers = [...listValues];
  }

  if (!sawHookLevel) {
    config.malformed = true;
    warnOnce(pi, ctx, "config-hook-level", `${CONFIG_FILE} has no valid hook_level; using strict`);
  }

  return config;
}

function allowedMcpServers(config: HarnessConfig): string[] {
  const custom = config.allowedMcpServersCustom?.split(",").map(item => item.trim()).filter(Boolean);
  if (custom && custom.length > 0) return custom;
  return config.allowedMcpServers ?? [];
}

function readProgressTail(cwd: string, lines: number): string {
  const text = readText(join(cwd, PROGRESS_FILE));
  if (!text) return "";
  return text.replace(/\r\n/g, "\n").trimEnd().split("\n").slice(-lines).join("\n");
}

/** Current sprint goal from contract.md, when the sprint has been drafted. */
function readSprintGoal(cwd: string, epic: string, sprint: number): string {
  if (!epic || sprint <= 0) return "";
  const sprintsDir = join(cwd, HARNESS_DIR, epic, "sprints");
  try {
    for (const name of readdirSync(sprintsDir)) {
      if (!name.startsWith(`sprint-${sprint}-`)) continue;
      const contract = readText(join(sprintsDir, name, "contract.md"));
      const match = contract ? /^goal:\s*(.+)$/m.exec(contract) : null;
      if (match) return match[1].trim().replace(/^["']|["']$/g, "").slice(0, 200);
    }
  } catch {
    // No sprints directory yet (plan in progress) — omit the goal line.
  }
  return "";
}

/** Stable per-session key. Subagents carry `agent.id`; the main session does not. */
function sessionKey(ctx: object): string {
  if ("agent" in ctx) {
    const agent = ctx.agent;
    if (agent && typeof agent === "object" && "id" in agent && typeof agent.id === "string" && agent.id) {
      return agent.id;
    }
  }
  return "main";
}

function buildHarnessContext(cwd: string): string {
  const state = readJson(join(cwd, STATE_FILE));
  if (!state) return "";

  const epic = asString(state.current_epic);
  const sprint = asNumber(state.current_sprint, 0);
  const goal = readSprintGoal(cwd, epic, sprint);
  const tail = readProgressTail(cwd, CONTEXT_PROGRESS_LINES);
  const rows = [
    "<harness-context>",
    `epic: ${epic || "none"}`,
    `sprint: ${sprint}`,
    `phase: ${asString(state.phase, "unknown")}`,
    `iteration: ${asNumber(state.iteration, 0)}`,
    ...(goal ? [`goal: ${goal}`] : []),
    `completed: ${asBoolean(state.completed)}`,
    `pending_human: ${asBoolean(state.pending_human)}`,
    `next_action: ${asString(state.next_action, "read .harness/_state.json")}`,
    "</harness-context>",
  ];
  if (tail) rows.push("<harness-progress-tail>", tail, "</harness-progress-tail>");
  return rows.join("\n");
}

/** Remove heredoc bodies so generated scripts/examples do not trip Tier-A. */
function stripHeredocBodies(command: string): string {
  const output: string[] = [];
  let marker: string | null = null;
  for (const line of command.replace(/\r\n/g, "\n").split("\n")) {
    if (marker) {
      if (line.trim() === marker) marker = null;
      continue;
    }
    output.push(line);
    const heredoc = /<<-?\s*['"]?([A-Za-z_][A-Za-z0-9_]*)['"]?/.exec(line);
    if (heredoc) marker = heredoc[1];
  }
  return output.join("\n");
}

/** Translate the POSIX character classes used by tier-a-patterns.txt. */
function toJsRegex(pattern: string): RegExp | null {
  const translated = pattern
    .replaceAll("[[:space:]]", "\\s")
    .replaceAll("[[:blank:]]", "[ \\t]")
    .replaceAll("[[:alnum:]]", "[A-Za-z0-9]")
    .replaceAll("[[:alpha:]]", "[A-Za-z]")
    .replaceAll("[[:digit:]]", "[0-9]")
    .replaceAll("[[:upper:]]", "[A-Z]")
    .replaceAll("[[:lower:]]", "[a-z]")
    .replaceAll("[[:punct:]]", "[!-/:-@\\[-`{-~]");
  try {
    // The shell guard matches line-by-line via grep; `m` preserves that.
    return new RegExp(translated, "m");
  } catch {
    return null;
  }
}

function matchTierA(pi: HookAPI, ctx: object, cwd: string, subject: string): TierMatch | null {
  const patterns = readText(join(cwd, PATTERNS_FILE));
  if (!patterns) return null;

  const command = stripHeredocBodies(subject);
  for (const raw of patterns.replace(/\r\n/g, "\n").split("\n")) {
    const pattern = raw.trim();
    if (!pattern || pattern.startsWith("#")) continue;
    const regex = toJsRegex(pattern);
    if (!regex) {
      warnOnce(pi, ctx, `pattern-invalid:${pattern}`, `invalid Tier-A pattern skipped: ${pattern}`);
      continue;
    }
    if (regex.test(command)) return { pattern, subject };
  }
  return null;
}

function appendProgress(cwd: string, line: string): void {
  mkdirSync(join(cwd, HARNESS_DIR), { recursive: true });
  const path = join(cwd, PROGRESS_FILE);
  if (!existsSync(path)) writeFileSync(path, "# Harness progress log (append-only)\n\n", "utf8");
  appendFileSync(path, `${line}\n`, "utf8");
}

function utcNow(): string {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
}

function denyTierA(pi: HookAPI, ctx: object, cwd: string, level: HookLevel, match: TierMatch): string | null {
  const ts = utcNow();
  const line = `- ${ts} | TIER-A MATCH | pattern=${match.pattern} | cmd=${match.subject}`;
  appendProgress(cwd, line);

  if (level === "warn") return null;

  const statePath = join(cwd, STATE_FILE);
  const state = readJson(statePath);
  if (state) {
    // Archive an already-resolved event before replacing the live slot.
    const last = state.tier_a_last;
    if (last && typeof last === "object" && !Array.isArray(last) && "resolution" in last && last.resolution) {
      try {
        mkdirSync(join(cwd, HARNESS_DIR, "_audit"), { recursive: true });
        appendFileSync(join(cwd, AUDIT_FILE), `${JSON.stringify(last)}\n`, "utf8");
      } catch {
        // Audit is best-effort; the deny still applies.
      }
    }
    state.pending_human = true;
    state.tier_a_history = [];
    state.tier_a_last = { pattern: match.pattern, cmd: match.subject, ts };
    try {
      writeJsonAtomic(statePath, state);
    } catch {
      warnOnce(pi, ctx, "tier-a-state", "Tier-A matched but _state.json could not be updated");
    }
  }
  return `tier-a denied: pattern=${match.pattern} cmd=${match.subject} — requires human approval`;
}

function mcpDecision(pi: HookAPI, ctx: object, cwd: string, toolName: string, config: HarnessConfig): string | null {
  const servers = allowedMcpServers(config);
  if (servers.includes("*")) {
    const marker = join(cwd, WILDCARD_MARKER);
    if (!existsSync(marker)) {
      appendProgress(
        cwd,
        `- ${utcNow()} | WARN mcp-allowlist: wildcard (*) in allow-list — every MCP server is accepted; tighten once the project is hardened`,
      );
      try {
        writeFileSync(marker, "", "utf8");
      } catch {
        // Marker is advisory.
      }
    }
    return null;
  }

  const rest = toolName.startsWith("mcp__") ? toolName.slice("mcp__".length) : toolName;
  const claudeServer = rest.includes("__") ? rest.split("__")[0] : "";
  for (const server of servers) {
    if (claudeServer && server === claudeServer) return null;
    if (rest === server || rest.startsWith(`${server}_`)) return null;
  }

  if (config.missing) {
    warnOnce(pi, ctx, "mcp-config-missing", `no ${CONFIG_FILE}; denying MCP call ${toolName}`);
    return `mcp-allowlist: no _config.yml; denying ${toolName}`;
  }
  return `mcp-allowlist: server "${rest}" not in allow-list [${servers.join(" ")}] for tool ${toolName}`;
}

function restoreContext(cwd: string, config: HarnessConfig): string {
  const configuredTail = Number.parseInt(config.progressTailLines ?? "", 10);
  const envTail = Number.parseInt(process.env.HARNESS_PROGRESS_TAIL ?? "", 10);
  const tailLines = Number.isFinite(envTail) ? envTail : Number.isFinite(configuredTail) ? configuredTail : 30;

  const statePath = join(cwd, STATE_FILE);
  const progressPath = join(cwd, PROGRESS_FILE);
  const rows = ["<harness-restore>"];

  const state = readText(statePath);
  if (state !== null) {
    rows.push(`<state file="${STATE_FILE}">`, state.trimEnd(), "</state>");
  } else {
    rows.push('<state missing="true"/>');
  }

  const progress = readText(progressPath);
  if (progress !== null) {
    const tail = progress.replace(/\r\n/g, "\n").trimEnd().split("\n").slice(-tailLines).join("\n");
    rows.push(`<progress file="${PROGRESS_FILE}" tail="${tailLines}">`, tail, "</progress>");
  } else {
    rows.push('<progress missing="true"/>');
  }

  rows.push("</harness-restore>");
  return rows.join("\n");
}

function capValue(state: JsonObject, key: string, configured: string | undefined, fallback: number): string {
  if (typeof state[key] === "number" && Number.isFinite(state[key])) return String(state[key]);
  if (configured !== undefined && configured !== "") return configured;
  return String(fallback);
}

function finalStopReason(cwd: string, config: HarnessConfig): { decision: "block"; reason: string } | null {
  const state = readJson(join(cwd, STATE_FILE));
  if (!state) return null;

  const epic = asString(state.current_epic);
  if (!epic || epic === "null") return null;
  if (asNumber(state.current_sprint, 0) === 0) return null;
  if (NON_LOOP_PHASES[asString(state.phase)]) return null;
  if (asBoolean(state.completed) || asBoolean(state.pending_human)) return null;

  if (asBoolean(state.pending_worker_exit)) {
    state.pending_worker_exit = false;
    writeJsonAtomic(join(cwd, STATE_FILE), state);
    return null;
  }

  const iteration = asNumber(state.iteration, 0);
  const cumulativeCost = asNumber(state.cumulative_cost_usd, 0);
  const stagnation = asNumber(state.rubric_stagnation_count, 0);
  const maxIterationsRaw = capValue(state, "max_iterations", config.maxIterations, DEFAULT_MAX_ITERATIONS);
  const maxWallRaw = capValue(state, "max_wall_time_sec", config.maxWallTimeSec, DEFAULT_MAX_WALL_TIME_SEC);
  const maxCostRaw = capValue(state, "max_cost_usd", config.maxCostUsd, DEFAULT_MAX_COST_USD);
  const maxStagnationRaw = config.rubricStagnationN ?? String(DEFAULT_RUBRIC_STAGNATION_N);

  const maxIterations = Number(maxIterationsRaw);
  const maxWall = Number(maxWallRaw);
  const maxCost = Number(maxCostRaw);
  const maxStagnation = Number(maxStagnationRaw);

  let elapsed = 0;
  const startTime = asString(state.start_time);
  if (startTime) {
    const start = Date.parse(startTime);
    if (Number.isFinite(start)) elapsed = Math.max(0, Math.floor((Date.now() - start) / 1000));
  }

  if (iteration >= maxIterations) return null;
  if (elapsed >= maxWall) return null;
  if (cumulativeCost >= maxCost) return null;
  if (stagnation >= maxStagnation) return null;

  return {
    decision: "block",
    reason: `harness loop incomplete: iter=${iteration}/${maxIterationsRaw}, wall=${elapsed}s/${maxWallRaw}s, cost=$${cumulativeCost}/$${maxCostRaw}, stagnation=${stagnation}/${maxStagnationRaw}`,
  };
}

export default function harnessGuard(pi: HookAPI): void {
  pi.on("before_agent_start", async (_event, ctx) => {
    try {
      const config = readConfig(pi, ctx, ctx.cwd);
      const warning = config.missing
        ? "<harness-warning>.harness/_config.yml is missing; using hook_level=strict and denying MCP calls.</harness-warning>"
        : config.malformed
          ? "<harness-warning>.harness/_config.yml has no valid hook_level; using strict.</harness-warning>"
          : "";
      const content = [buildHarnessContext(ctx.cwd), warning].filter(Boolean).join("\n");
      if (!content) return;

      // omp rebinds this factory to subagent sessions; dedupe per session so a
      // subagent still receives the cursor once even when the main session
      // already saw the same state.
      const key = sessionKey(ctx);
      if (content === lastInjectedContext.get(key)) return;
      lastInjectedContext.set(key, content);

      return {
        message: {
          customType: "harness-context",
          content,
          display: false,
        },
      };
    } catch {
      return;
    }
  });

  pi.on("tool_call", async (event, ctx) => {
    try {
      const config = readConfig(pi, ctx, ctx.cwd);
      if (config.hookLevel === "minimal") return;

      if (event.toolName === "bash") {
        const command = String(event.input.command ?? "");
        if (!command) return;
        const match = matchTierA(pi, ctx, ctx.cwd, command);
        if (!match) return;
        const reason = denyTierA(pi, ctx, ctx.cwd, config.hookLevel, match);
        if (reason) return { block: true, reason };
        return;
      }

      if (event.toolName === "edit" || event.toolName === "write") {
        const path = String(event.input.path ?? "");
        if (!path) return;
        const match = matchTierA(pi, ctx, ctx.cwd, path);
        if (!match) return;
        const reason = denyTierA(pi, ctx, ctx.cwd, config.hookLevel, match);
        if (reason) return { block: true, reason };
        return;
      }

      if (config.hookLevel === "strict" && event.toolName.startsWith("mcp__")) {
        const reason = mcpDecision(pi, ctx, ctx.cwd, event.toolName, config);
        if (reason) return { block: true, reason };
      }
    } catch {
      // Fail open: a broken guard must not wedge every tool call.
      return;
    }
  });

  pi.on("tool_result", async (event, ctx) => {
    try {
      if (event.isError) return;
      if (event.toolName !== "edit" && event.toolName !== "write") return;
      const path = String(event.input.path ?? "");
      if (!path) return;

      const config = readConfig(pi, ctx, ctx.cwd);
      const state = readJson(join(ctx.cwd, STATE_FILE));
      const phase = state ? asString(state.phase, "unknown") : "unknown";
      const agent = process.env.HARNESS_AGENT ?? "omp";
      const ts = utcNow();

      if (config.toolLogExternal) {
        mkdirSync(join(ctx.cwd, HARNESS_DIR), { recursive: true });
        const row: JsonObject = { ts, agent, phase, tool: event.toolName };
        if (path) row.path = path;
        appendFileSync(join(ctx.cwd, TOOL_LOG_FILE), `${JSON.stringify(row)}\n`, "utf8");
        return;
      }

      appendProgress(ctx.cwd, `- ${ts} | agent=${agent} | phase=${phase} | ${event.toolName} | ${path}`);
    } catch {
      return;
    }
  });

  pi.on("session.compacting", async (_event, ctx) => {
    try {
      const config = readConfig(pi, ctx, ctx.cwd);
      const context = restoreContext(ctx.cwd, config);
      return { context: [context] };
    } catch {
      return;
    }
  });

  pi.on("session_stop", async (event, ctx) => {
    // omp sets this when a refusal already fired in the current chain.
    if (event.stop_hook_active) return;
    try {
      const config = readConfig(pi, ctx, ctx.cwd);
      const decision = finalStopReason(ctx.cwd, config);
      if (decision) return decision;
      return;
    } catch {
      // Never trap the session because the guard broke.
      return;
    }
  });
}
